import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const marker =
  "AE_UI_POLISH_PACK_13_RUNTIME_STRUCTURE_START";

const mainRelative =
  "artifacts/animated-effects/src/main.ts";

const styleRelative =
  "artifacts/animated-effects/src/style.css";

const moduleRelative =
  "artifacts/animated-effects/src/pack09/uiStructuralFix.ts";

const mainFile =
  path.join(
    root,
    mainRelative,
  );

const styleFile =
  path.join(
    root,
    styleRelative,
  );

const moduleFile =
  path.join(
    root,
    moduleRelative,
  );

function fail(
  message,
) {
  console.error(
    "\nERROR:",
    message,
  );
  process.exit(
    1,
  );
}

if (
  !fs.existsSync(
    path.join(
      root,
      "pnpm-workspace.yaml",
    ),
  )
) {
  fail(
    "Uruchom z katalogu głównego aplikacja-turnieje-live.",
  );
}

for (
  const file of [
    mainFile,
    styleFile,
  ]
) {
  if (
    !fs.existsSync(
      file,
    )
  ) {
    fail(
      "Brak wymaganego pliku: " +
      path.relative(
        root,
        file,
      ),
    );
  }
}

const currentStyle =
  fs.readFileSync(
    styleFile,
    "utf8",
  );

if (
  !currentStyle.includes(
    "AE_UI_POLISH_PACK_12_STRUCTURAL_START",
  )
) {
  fail(
    "Pack 13 wymaga zainstalowanego Pack 12.",
  );
}

if (
  currentStyle.includes(
    marker,
  )
) {
  console.log(
    "UI Polish Pack 13 jest już zainstalowany.",
  );
  process.exit(
    0,
  );
}

const stamp =
  new Date()
    .toISOString()
    .replace(
      /[:.]/g,
      "-",
    )
    .replace(
      "T",
      "_",
    )
    .replace(
      "Z",
      "",
    );

const backupRoot =
  path.join(
    root,
    ".ae-pack-backup",
    `pack-13-ui-runtime-structure-${stamp}`,
  );

const touched = [
  mainRelative,
  styleRelative,
  moduleRelative,
];

const existed = [];

for (
  const relative of
    touched
) {
  const source =
    path.join(
      root,
      relative,
    );

  if (
    !fs.existsSync(
      source,
    )
  ) {
    continue;
  }

  existed.push(
    relative,
  );

  const backup =
    path.join(
      backupRoot,
      relative,
    );

  fs.mkdirSync(
    path.dirname(
      backup,
    ),
    {
      recursive:
        true,
    },
  );

  fs.copyFileSync(
    source,
    backup,
  );
}

fs.mkdirSync(
  backupRoot,
  {
    recursive:
      true,
  },
);

fs.writeFileSync(
  path.join(
    backupRoot,
    "backup-manifest.json",
  ),
  JSON.stringify(
    {
      pack:
        "Animated Effects UI Polish Pack 13 Runtime Structure",
      touched,
      existed,
    },
    null,
    2,
  ) + "\n",
  "utf8",
);

const moduleSource =
  Buffer.from(
    "",
    "hex",
  ).toString(
    "utf8",
  );

fs.mkdirSync(
  path.dirname(
    moduleFile,
  ),
  {
    recursive:
      true,
  },
);

fs.writeFileSync(
  moduleFile,
  moduleSource,
  "utf8",
);

let main =
  fs.readFileSync(
    mainFile,
    "utf8",
  );

if (
  !main.includes(
    'from "./pack09/uiStructuralFix"',
  )
) {
  const importText =
`import {
  installPack13StructuralUiFix,
} from "./pack09/uiStructuralFix";`;

  const polishImport =
    /import\s*\{\s*installPack09UiPolish\s*,?\s*\}\s*from\s*["']\.\/pack09\/uiPolish["']\s*;?/m;

  const match =
    main.match(
      polishImport,
    );

  if (match) {
    main =
      main.replace(
        polishImport,
        match[0] +
        "\n\n" +
        importText,
      );
  } else if (
    main.includes(
      'import "./style.css";',
    )
  ) {
    main =
      main.replace(
        'import "./style.css";',
        'import "./style.css";' +
        "\n\n" +
        importText,
      );
  } else {
    fail(
      "Nie znaleziono bezpiecznego miejsca na import Pack13 w main.ts.",
    );
  }
}

if (
  !main.includes(
    "installPack13StructuralUiFix();",
  )
) {
  if (
    main.includes(
      "installPack09UiPolish();",
    )
  ) {
    main =
      main.replace(
        "installPack09UiPolish();",
        "installPack09UiPolish();" +
        "\n" +
        "installPack13StructuralUiFix();",
      );
  } else if (
    main.includes(
      "installPack09Customization();",
    )
  ) {
    main =
      main.replace(
        "installPack09Customization();",
        "installPack09Customization();" +
        "\n" +
        "installPack13StructuralUiFix();",
      );
  } else {
    main +=
      "\ninstallPack13StructuralUiFix();\n";
  }
}

fs.writeFileSync(
  mainFile,
  main,
  "utf8",
);

const cssPatch =
  Buffer.from(
    "",
    "hex",
  ).toString(
    "utf8",
  );

fs.writeFileSync(
  styleFile,
  currentStyle.trimEnd() +
  "\n\n" +
  cssPatch.trim() +
  "\n",
  "utf8",
);

const rollbackPath =
  path.join(
    root,
    "ae-ui-polish-pack-13-runtime-structure-rollback.mjs",
  );

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const backupRoot =
  ${JSON.stringify(
    backupRoot,
  )};

const manifest =
  JSON.parse(
    fs.readFileSync(
      path.join(
        backupRoot,
        "backup-manifest.json",
      ),
      "utf8",
    ),
  );

const existed =
  new Set(
    manifest.existed,
  );

for (
  const relative of
    manifest.touched
) {
  const target =
    path.join(
      root,
      relative,
    );

  const backup =
    path.join(
      backupRoot,
      relative,
    );

  if (
    existed.has(
      relative,
    )
  ) {
    fs.mkdirSync(
      path.dirname(
        target,
      ),
      {
        recursive:
          true,
      },
    );

    fs.copyFileSync(
      backup,
      target,
    );
  } else {
    fs.rmSync(
      target,
      {
        recursive:
          true,
        force:
          true,
      },
    );
  }
}

console.log(
  "UI Polish Pack 13 cofnięty.",
);
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

console.log("");
console.log("==========================================================");
console.log(" Animated Effects UI Polish Pack 13 RUNTIME FIX INSTALLED");
console.log("==========================================================");
console.log("");
console.log("Zakres: tylko UI/UX.");
console.log("");
console.log("Tym razem naprawa działa na faktycznym DOM po renderze:");
console.log(" - Widok + Sortuj są fizycznie przenoszone do jednego kontenera");
console.log(" - + nieaktywnej karty jest fizycznie wyciągany z wrappera Pack06");
console.log(" - nieaktywna karta ma prawdziwy układ: gwiazdka | treść | +");
console.log(" - aktywna karta zachowuje osobny rząd: - | licznik | +");
console.log(" - MutationObserver ponawia strukturę po każdym rerenderze biblioteki");
console.log(" - inspector ma jeszcze ciaśniejsze odstępy bez zmiany logiki");
console.log("");
console.log(
  "Backup:",
  path.relative(
    root,
    backupRoot,
  ),
);
console.log(
  "Rollback: .\\ae-ui-polish-pack-13-runtime-structure-rollback.mjs",
);
console.log("");
console.log("Teraz:");
console.log("  pnpm --filter animated-effects run typecheck");
console.log("  pnpm --filter animated-effects run build");
